const items = $input.all();

const companyName = $('Supabase1').first().json.company_name;
const nseSymbol = $('Supabase1').first().json.nse_symbol;

const result = {
  company_name: companyName,
  nse_symbol: nseSymbol,
  investment_rationale: '',
  company_background: '',
  business_model: '',
  management_analysis: '',
  corporate_governance: '',
  industry_overview: '',
  industry_tailwinds: '',
  demand_drivers: '',
  industry_risks: '',
  saarthi_framework: '',
  entry_review_exit_strategy: '',
  scenario_analysis: '',
  rating: '',
  target_price: '',
  upside_percentage: '',
  current_market_price: ''
};

for (const item of items) {
  const key = item.json.section_key;
  const content = item.json.content;
  if (key in result) {
    result[key] = content;
  }
}

return [{ json: result }];

