if (!script || script.trim() === '') {
  throw new Error('podcast_script is empty in research_reports. Run Script Generator workflow first.');
}

const lines = script.split('\n').filter(line => line.trim() !== '');
const audioSegments = [];

for (const line of lines) {
  const trimmed = line.trim();
  if (trimmed.startsWith('Host A:')) {
    audioSegments.push({
      text: trimmed.replace(/^Host A:/i, '').trim(),
      speaker_name: speakerA,
      speaker: 'Ananya'
    });
  } else if (trimmed.startsWith('Host B:')) {
    audioSegments.push({
      text: trimmed.replace(/^Host B:/i, '').trim(),
      speaker_name: speakerB,
      speaker: 'Ayush'
    });
  }
}

if (audioSegments.length === 0) {
  throw new Error('No dialogue lines found. Script must have "Host A:" and "Host B:" prefixes. Preview: ' + script.substring(0, 200));
}

console.log('Parsed ' + audioSegments.length + ' dialogue segments.');

// Return one item per segment so HTTP Request node processes each one
return audioSegments;

