});

console.log('Merging ' + audioBuffers.length + ' WAV segments in pure JS...');

// WAV header is 44 bytes
// Keep full first file, strip 44-byte header from all subsequent files
const WAV_HEADER_SIZE = 44;
const firstBuffer = audioBuffers[0];

// Calculate total PCM data size (all files minus headers of files 2+)
let totalPcmSize = firstBuffer.length - WAV_HEADER_SIZE;
for (let i = 1; i < audioBuffers.length; i++) {
  totalPcmSize += audioBuffers[i].length - WAV_HEADER_SIZE;
}

// Update the data chunk size in the WAV header (bytes 40-43)
const mergedBuffer = Buffer.concat(audioBuffers.map((buf, i) => {
  return i === 0 ? buf : buf.slice(WAV_HEADER_SIZE);
}));

// Fix WAV header sizes
// Byte 4-7: total file size - 8
mergedBuffer.writeUInt32LE(mergedBuffer.length - 8, 4);
// Byte 40-43: data chunk size
mergedBuffer.writeUInt32LE(totalPcmSize, 40);

const mergedBase64 = mergedBuffer.toString('base64');
console.log('Merged WAV size: ' + mergedBuffer.length + ' bytes');

return [{
